def read_evaluation_receipt(path: str | Path) -> Mapping[str, Any]:
    """Read canonical durable receipt JSON and verify its content digest."""

    destination = Path(path)
    try:
        raw = destination.read_bytes()
        value = json.loads(raw)
    except (OSError, json.JSONDecodeError) as error:
        raise MeasurementContractError("evaluation receipt is unreadable") from error
    # Ensure the on-disk bytes are canonical JSON plus a newline.
    expected = canonical_json_bytes(value) + b"\n"
    if raw != expected:
        raise MeasurementContractError("evaluation receipt bytes are not canonical")
    verified = verify_serialized_evaluation_receipt(value)
    # Additionally, ensure that the sealed digest matches the content.
    # Build a temporary receipt from the verified mapping to detect tampering
    # with fields like deferred_leaf_ids that would alter the content digest.
    try:
        temp_receipt = EvaluationReceipt(**value)
    except MeasurementContractError:
        # If the mapping does not conform to a receipt, verification already
        # failed above.
        pass
    else:
        if temp_receipt.receipt_sha256 is not None:
            sealed = seal_evaluation_receipt(temp_receipt)
            if sealed.receipt_sha256 != value.get("receipt_sha256"):
                raise MeasurementContractError("receipt_sha256 does not match receipt content")
        else:
            # For an unsealed receipt, the content digest must not conflict with
            # a present digest.
            if value.get("receipt_sha256") is not None:
                raise MeasurementContractError("receipt_sha256 is present on unsealed receipt")
    return verified

